_tally = {"passed": 0, "total": 0}

def check(label, make_actual, expected):
    """Run one check. It never raises, so the notebook always runs from top to bottom."""
    _tally["total"] += 1
    try:
        actual = make_actual()
    except Exception as error:
        print(f"error  {label}: {type(error).__name__}: {error}")
        return
    if actual == expected:
        _tally["passed"] += 1
        print(f"pass   {label}")
    else:
        print(f"todo   {label}: got {actual!r}")

def raises(make_actual, error_type):
    """True when the call raises error_type, False when it raises anything else or nothing."""
    try:
        make_actual()
    except error_type:
        return True
    except Exception:
        return False
    return False

def score():
    print(f"\nScore: {_tally['passed']} of {_tally['total']} checks pass")

from unittest.mock import patch

def protected_updates(call, minimum):
    # Functional equality alone does not prove synchronization: append is atomic
    # in CPython. Count scopes on locks created by the exercise function,
    # excluding Queue and Thread's internal bookkeeping locks.
    real_lock = threading.Lock
    import sys
    entries = [0]
    class ObservedLock:
        def __init__(self):
            self.lock = real_lock()
            self.tracked = sys._getframe(1).f_code.co_name in {'count_with_lock', 'sum_with_queue'}
        def __getattr__(self, name):
            return getattr(self.lock, name)
        def __enter__(self):
            self.lock.acquire()
            if self.tracked:
                entries[0] += 1
            return self
        def __exit__(self, *args):
            self.lock.release()
    with patch.object(threading, 'Lock', ObservedLock):
        call()
    return entries[0] >= minimum

check("count_with_lock(4, 1000) == 4000", lambda: count_with_lock(4, 1000), 4000)
check("count_with_lock(1, 5) == 5", lambda: count_with_lock(1, 5), 5)
check('zero increments', lambda: count_with_lock(3, 0), 0)
check('many workers', lambda: count_with_lock(8, 2000), 16000)
check('single increment', lambda: count_with_lock(5, 1), 5)
check('lock protects every update', lambda: protected_updates(lambda: count_with_lock(4, 2500), 10000), True)

